import typing

from jsilib import _utils
from jsilib._compat import asyncio

from . import exc
from .interface import IAcceptor, IStream

__all__ = export = _utils.ExportList()


@export
class ForwardingAcceptor(IAcceptor):
    """An acceptor that awaits on a queue for an incoming :class:`IStream`
    connection object."""

    def __init__(self):
        self._closed = False
        self._queue: asyncio.Queue[typing.Optional[IStream]] = asyncio.Queue()

    def dispatch(self, stream: IStream):
        self._queue.put_nowait(stream)

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            self._queue.put_nowait(None)

    async def accept(self) -> IStream:
        if self._closed:
            raise exc.AcceptorClosedError()
        maybe_stream = await self._queue.get()
        if maybe_stream is None:
            raise exc.AcceptorClosedError()
        return maybe_stream
